import{a as e,i as t,r as n,t as r}from"./app-D1At6QKN.js";var i=JSON.parse(`{"path":"/guide/ai.html","title":"AI 对话","lang":"zh-CN","frontmatter":{},"git":{"updatedTime":1789795290000,"contributors":[{"name":"ShiroMizu","username":"","email":"ShiroMizuTan@163.com","commits":1}],"changelog":[{"hash":"ee8e87b1d667cc5e38d7121fcc93fb5393ad2b0c","time":1789795290000,"email":"ShiroMizuTan@163.com","author":"ShiroMizu","message":"docs: add AI chat page"}]},"filePathRelative":"guide/ai.md"}`),a={name:`ai.md`};function o(r,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[t(`<h1 id="ai-对话" tabindex="-1"><a class="header-anchor" href="#ai-对话"><span>AI 对话</span></a></h1><p>雪希可以和你自由聊天，也会记住关于你的事。</p><h2 id="开始对话" tabindex="-1"><a class="header-anchor" href="#开始对话"><span>开始对话</span></a></h2><table><thead><tr><th>触发方式</th><th>参数</th><th>示例</th><th>说明</th></tr></thead><tbody><tr><td><code>ai</code> / <code>chat</code> / <code>聊天</code></td><td><code>内容</code></td><td><code>.ai 今天天气怎么样</code></td><td>带前缀发起对话</td></tr><tr><td><code>雪希</code> / <code>yuki</code></td><td><code>内容</code></td><td><code>雪希 在干嘛</code></td><td>呼叫名 + 内容，<strong>支持无前缀</strong>，群聊里直接发送即可</td></tr></tbody></table><div class="hint-container tip"><p class="hint-container-title">提示</p><p>只要带内容，呼叫名后可以不写前缀。例如群里直接发 <code>雪希 陪我聊会儿</code> 就会触发。 但只发呼叫名（如单发一句 <code>雪希</code>）不会进入对话，而是随机回一条呼叫回复语。</p></div><h2 id="支持的输入" tabindex="-1"><a class="header-anchor" href="#支持的输入"><span>支持的输入</span></a></h2><table><thead><tr><th>类型</th><th>示例</th><th>说明</th></tr></thead><tbody><tr><td>文字</td><td><code>.ai 推荐一首歌</code></td><td>普通对话</td></tr><tr><td>图片</td><td>发送 <code>.ai</code> + 图片</td><td>会描述图片内容；纯图无文字时也会自动处理</td></tr><tr><td>图片 + 文字</td><td><code>.ai 这张图好看吗</code> + 图片</td><td>结合图片和文字回答</td></tr></tbody></table><h2 id="它会记住你" tabindex="-1"><a class="header-anchor" href="#它会记住你"><span>它会记住你</span></a></h2><p>聊天中提到的<strong>长期偏好、身份信息、正在进行的计划和目标</strong>会被自动记住， 之后聊天时能自然地用到，不需要重复说明。</p><ul><li>只记关于你的<strong>稳定事实</strong>，比如「我平时都用中文」「我在准备考研」</li><li>不会记一次性问题、临时情绪、闲聊内容</li><li>记忆按用户隔离，<strong>私聊的内容不会出现在群里</strong></li><li>群聊里产生的记忆会进群共享池，同群所有人都能受益</li></ul><h2 id="会不会跨群泄露我的信息" tabindex="-1"><a class="header-anchor" href="#会不会跨群泄露我的信息"><span>会不会跨群泄露我的信息</span></a></h2><p>不会。私聊记忆只有你和雪希知道。 群聊中属于<strong>别人</strong>的记忆在注入时会被标注，雪希不会把你的事当作别人的来回答，反之亦然。</p><h2 id="清空对话历史" tabindex="-1"><a class="header-anchor" href="#清空对话历史"><span>清空对话历史</span></a></h2><table><thead><tr><th>指令</th><th>示例</th><th>权限</th><th>说明</th></tr></thead><tbody><tr><td><code>清空AI历史</code> / <code>清空聊天记录</code> / <code>重置AI记忆</code></td><td><code>.清空AI历史</code></td><td>所有人</td><td>清空与雪希的聊天上下文</td></tr></tbody></table><div class="hint-container warning"><p class="hint-container-title">注意</p><p>该指令清空的是<strong>对话上下文</strong>（近期聊天记录），让它忘记刚才聊过什么。 已经形成的长期记忆不会被删除。</p></div><h2 id="管理员指令" tabindex="-1"><a class="header-anchor" href="#管理员指令"><span>管理员指令</span></a></h2><p>以下指令仅管理员可用，用于观察记忆系统的运行状态。</p><table><thead><tr><th>指令</th><th>参数</th><th>示例</th><th>说明</th></tr></thead><tbody><tr><td><code>记忆状态</code> / <code>AI记忆状态</code></td><td>无</td><td><code>.记忆状态</code></td><td>查看记忆池条数与可用性</td></tr><tr><td><code>记忆检查</code> / <code>AI记忆检查</code></td><td><code>文本</code></td><td><code>.记忆检查 我喜欢喝美式</code></td><td>用给定文本试跑一次召回，回显命中分数与内容</td></tr></tbody></table><h3 id="记忆状态" tabindex="-1"><a class="header-anchor" href="#记忆状态"><span>记忆状态</span></a></h3><p>输出记忆系统的可用性与各记忆池条数：</p><ul><li><strong>个人记忆池</strong>：当前用户自己的记忆条数</li><li><strong>本群共享记忆池</strong>：该群所有人共享的记忆条数（仅群聊显示）</li><li>召回门槛：当前生效的条数与相似度阈值</li></ul><h3 id="记忆检查" tabindex="-1"><a class="header-anchor" href="#记忆检查"><span>记忆检查</span></a></h3><p>用来诊断「为什么它没想起某件事」。会列出检索到的记忆、相似度分数和是否达到阈值：</p><table><thead><tr><th>标记</th><th>含义</th></tr></thead><tbody><tr><td><code>+</code></td><td>分数达到阈值，线上会被注入</td></tr><tr><td><code>-</code></td><td>分数低于阈值，线上会被挡掉（检索到了但没用上）</td></tr></tbody></table><p>分数列显示 <code>原始相似度 → 加权后排序分</code>，并附记忆年龄。 排序会参考记忆的新鲜度，所以只看原始分会和实际顺序有出入。</p><p>群聊中会同时列出个人池与群池的结果，便于确认命中的是哪个池。</p><h2 id="常见情况" tabindex="-1"><a class="header-anchor" href="#常见情况"><span>常见情况</span></a></h2><table><thead><tr><th>情况</th><th>说明</th></tr></thead><tbody><tr><td>短消息没生效</td><td>太短的消息不会触发记忆检索，正常说话即可</td></tr><tr><td>说了一遍没记住</td><td>只有长期稳定的信息才会被记，一次性内容不会存</td></tr><tr><td>记忆条数不增长</td><td>重复提到同一件事会刷新已有记忆而不是新增；闲聊不会产生记忆</td></tr><tr><td>群里问它我的喜好</td><td>群聊会同时看你的个人记忆和本群共享记忆</td></tr></tbody></table><div class="hint-container tip"><p class="hint-container-title">提示</p><p>记忆系统完全自动运行，不需要手动录入。正常聊天就行。</p></div>`,29)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};